import{_ as i,c as a,o as t,ah as e}from"./chunks/framework.DYJPYqf_.js";const g=JSON.parse('{"title":"WSL 使用 Windows v2rayN 代理（10808 端口）完整教程","description":"","frontmatter":{},"headers":[],"relativePath":"other/wslProxy.md","filePath":"other/wslProxy.md","lastUpdated":1787131233000}'),n={name:"other/wslProxy.md"};function l(p,s,d,h,o,r){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="wsl-使用-windows-v2rayn-代理-10808-端口-完整教程" tabindex="-1">WSL 使用 Windows v2rayN 代理（10808 端口）完整教程 <a class="header-anchor" href="#wsl-使用-windows-v2rayn-代理-10808-端口-完整教程" aria-label="Permalink to “WSL 使用 Windows v2rayN 代理（10808 端口）完整教程”">​</a></h1><hr><h2 id="_1-确认-windows-主机的真实-ip-wsl-访问-windows-必须用它" tabindex="-1">1. 确认 Windows 主机的真实 IP（WSL 访问 Windows 必须用它） <a class="header-anchor" href="#_1-确认-windows-主机的真实-ip-wsl-访问-windows-必须用它" aria-label="Permalink to “1. 确认 Windows 主机的真实 IP（WSL 访问 Windows 必须用它）”">​</a></h2><p>在 WSL 中执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip route</span></span></code></pre></div><p>你会看到类似(PS:如果你看到的地址，在下面测试时不可用，那么就去windows中使用cmd命令ipconfig查看你windows的ip地址，可以用那个地址)：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>default via 10.154.1.42 dev eth0</span></span></code></pre></div><p>其中：</p><ul><li><strong>10.154.1.42</strong> 就是 Windows 主机的真实 IP</li><li>WSL 不能用 127.0.0.1 访问 Windows</li><li>必须用这个 IP 才能访问 Windows 的代理端口</li></ul><p>你已经确认 Windows 主机 IP 为 <strong>10.154.1.42</strong>。</p><hr><h2 id="_2-测试-wsl-是否能访问-windows-的代理端口" tabindex="-1">2. 测试 WSL 是否能访问 Windows 的代理端口 <a class="header-anchor" href="#_2-测试-wsl-是否能访问-windows-的代理端口" aria-label="Permalink to “2. 测试 WSL 是否能访问 Windows 的代理端口”">​</a></h2><p>在 WSL 中执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nc -vz 10.154.1.42 10808</span></span></code></pre></div><p>你得到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Connection to 10.154.1.42 10808 port [tcp/*] succeeded!</span></span></code></pre></div><p>说明：</p><ul><li>Windows v2rayN 的代理端口 <strong>10808 正在监听</strong></li><li>WSL 可以访问这个端口</li><li>网络链路正常</li></ul><hr><h2 id="_3-在-wsl-中设置持久化代理变量-写入-bashrc" tabindex="-1">3. 在 WSL 中设置持久化代理变量（写入 ~/.bashrc） <a class="header-anchor" href="#_3-在-wsl-中设置持久化代理变量-写入-bashrc" aria-label="Permalink to “3. 在 WSL 中设置持久化代理变量（写入 ~/.bashrc）”">​</a></h2><p>打开 <code>.bashrc</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi ~/.bashrc</span></span></code></pre></div><p>加入以下内容（使用你的端口 10808 和 Windows 主机 IP 10.154.1.42）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export http_proxy=&quot;http://10.154.1.42:10808&quot;</span></span>
<span class="line"><span>export https_proxy=&quot;http://10.154.1.42:10808&quot;</span></span>
<span class="line"><span>export all_proxy=&quot;socks5://10.154.1.42:10808&quot;</span></span>
<span class="line"><span>export no_proxy=&quot;127.0.0.1,localhost,::1&quot;</span></span></code></pre></div><p>保存后让它生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>source ~/.bashrc</span></span></code></pre></div><hr><h2 id="_4-验证代理变量是否加载成功" tabindex="-1">4. 验证代理变量是否加载成功 <a class="header-anchor" href="#_4-验证代理变量是否加载成功" aria-label="Permalink to “4. 验证代理变量是否加载成功”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>env | grep -i proxy</span></span></code></pre></div><p>你应该看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http_proxy=http://10.154.1.42:10808</span></span>
<span class="line"><span>https_proxy=http://10.154.1.42:10808</span></span>
<span class="line"><span>all_proxy=socks5://10.154.1.42:10808</span></span></code></pre></div><p>说明 WSL 已经加载代理变量。</p><hr><h2 id="_5-测试-wsl-是否真正走代理-最关键" tabindex="-1">5. 测试 WSL 是否真正走代理（最关键） <a class="header-anchor" href="#_5-测试-wsl-是否真正走代理-最关键" aria-label="Permalink to “5. 测试 WSL 是否真正走代理（最关键）”">​</a></h2><p>执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget https://www.google.com</span></span></code></pre></div><p>你得到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Connecting to 10.154.1.42:10808... connected.</span></span>
<span class="line"><span>Proxy request sent, awaiting response... 200 OK</span></span>
<span class="line"><span>Saving to: ‘index.html’</span></span></code></pre></div><p>这说明：</p><ul><li>WSL 成功连接到 Windows 的代理端口</li><li>v2rayN 正常处理请求</li><li>Google 返回 200 OK</li><li>WSL 已经完全走代理</li></ul><p>你的代理链路已经完全跑通。</p><hr><h1 id="最终效果-你现在的状态" tabindex="-1">最终效果（你现在的状态） <a class="header-anchor" href="#最终效果-你现在的状态" aria-label="Permalink to “最终效果（你现在的状态）”">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>状态</th></tr></thead><tbody><tr><td>WSL → Windows 主机网络</td><td>✔ 正常</td></tr><tr><td>Windows v2rayN 10808 端口</td><td>✔ 正在监听</td></tr><tr><td>WSL 代理变量</td><td>✔ 正确设置为 10.154.1.42</td></tr><tr><td>持久化 <code>.bashrc</code></td><td>✔ 生效</td></tr><tr><td>wget/curl 走代理</td><td>✔ 成功</td></tr><tr><td>WSL 能访问 Google</td><td>✔ 成功</td></tr></tbody></table><p>你已经完成了整个 WSL 代理配置的全部步骤。</p>`,45)])])}const k=i(n,[["render",l]]);export{g as __pageData,k as default};
